INSERT INTO roles (role_name, description) SELECT 'Admin', 'IGNITE Admin' WHERE @new_role_0;
INSERT INTO roles (role_name, description) SELECT 'Manager', 'IGNITE Manager' WHERE @new_role_1;
INSERT INTO roles (role_name, description) SELECT 'Sales Staff', 'IGNITE Sales Staff' WHERE @new_role_2;
INSERT INTO permissions (permission_name, module, action, description) SELECT 'vehicles.view', 'vehicles', 'view', 'View vehicles' WHERE NOT EXISTS (SELECT 1 FROM permissions WHERE permission_name='vehicles.view');
INSERT INTO permissions (permission_name, module, action, description) SELECT 'vehicles.create', 'vehicles', 'create', 'Create vehicles' WHERE NOT EXISTS (SELECT 1 FROM permissions WHERE permission_name='vehicles.create');
INSERT INTO permissions (permission_name, module, action, description) SELECT 'vehicles.update', 'vehicles', 'update', 'Update vehicles' WHERE NOT EXISTS (SELECT 1 FROM permissions WHERE permission_name='vehicles.update');
INSERT INTO permissions (permission_name, module, action, description) SELECT 'vehicles.delete', 'vehicles', 'delete', 'Delete vehicles' WHERE NOT EXISTS (SELECT 1 FROM permissions WHERE permission_name='vehicles.delete');
INSERT INTO permissions (permission_name, module, action, description) SELECT 'customers.view', 'customers', 'view', 'View customers' WHERE NOT EXISTS (SELECT 1 FROM permissions WHERE permission_name='customers.view');
INSERT INTO permissions (permission_name, module, action, description) SELECT 'customers.create', 'customers', 'create', 'Create customers' WHERE NOT EXISTS (SELECT 1 FROM permissions WHERE permission_name='customers.create');
INSERT INTO permissions (permission_name, module, action, description) SELECT 'customers.update', 'customers', 'update', 'Update customers' WHERE NOT EXISTS (SELECT 1 FROM permissions WHERE permission_name='customers.update');
