INSERT INTO role_permissions (role_id, permission_id) SELECT r.role_id, p.permission_id FROM roles r CROSS JOIN permissions p WHERE r.role_name='Admin' AND p.permission_name IN ('vehicles.view','vehicles.create','vehicles.update','vehicles.delete','customers.view','customers.create','customers.update','inventory.view','inventory.create','sales.view','sales.create','sales.complete','invoices.view','reports.view','users.manage','roles.manage') AND @new_role_0;
INSERT INTO role_permissions (role_id, permission_id) SELECT r.role_id, p.permission_id FROM roles r CROSS JOIN permissions p WHERE r.role_name='Manager' AND p.permission_name IN ('vehicles.view','vehicles.create','vehicles.update','customers.view','customers.create','customers.update','inventory.view','inventory.create','sales.view','sales.create','sales.complete','invoices.view','reports.view') AND @new_role_1;
INSERT INTO role_permissions (role_id, permission_id) SELECT r.role_id, p.permission_id FROM roles r CROSS JOIN permissions p WHERE r.role_name='Sales Staff' AND p.permission_name IN ('vehicles.view','customers.view','customers.create','customers.update','sales.view','sales.create','sales.complete','invoices.view') AND @new_role_2;
